import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'questions/science'
DATA=[
("若某地 30 年平均氣溫逐步上升，且熱浪日數增加，這組資料最能支持哪項判斷？",["當地氣候型態可能正在改變","單日天氣一定由氣候決定","代表地震變多","可直接證明所有地區相同"],"A","長期平均與極端事件頻率都是氣候變化的指標，但仍需檢查資料品質與自然變異。","先確認長期尺度，再區分支持氣候趨勢與不能推出的全球結論。"),
("減緩氣候變遷與調適氣候變遷的差異，哪項正確？",["減緩是減少溫室氣體來源，調適是降低已發生或預期衝擊","兩者都只是在增加排放","減緩只處理洪水，調適只處理發電","兩者完全相同"],"A","減緩針對成因，例如節能與低碳能源；調適針對風險，例如防洪、耐熱與水資源管理。","先問措施是在處理成因還是降低衝擊。"),
("沿海城市因海平面上升而抬高堤防，這屬於哪類策略？",["調適","減少化石燃料燃燒","地震預測","物種分類"],"A","抬高堤防是降低海平面上升對城市造成的淹水風險，屬於調適。","看措施直接改變排放，還是保護人與環境免受衝擊。"),
("大眾運輸與再生能源政策主要可透過哪種方式減緩氣候變遷？",["降低化石燃料燃燒造成的溫室氣體排放","增加海岸侵蝕","使所有天氣固定","讓二氧化碳立刻歸零"],"A","減少燃油使用或改用低碳能源可降低排放速率，但不代表大氣二氧化碳立即歸零。","追蹤能源使用到排放量的變化，避免誇大效果。"),
("若要評估都市熱浪風險，除了溫度紀錄，還應優先加入哪項資料？",["老年人口、綠地與醫療可近性等暴露與脆弱度資料","只看一棟建築顏色","只看月相","只看一次降雨"],"A","風險不只由危害強度決定，也與暴露人口、脆弱度和應變能力有關。","將危害、暴露、脆弱度與應變能力分開整理。"),
("氣候模型預測未來降雨型態時，最適當的使用方式是？",["比較多種情境與不確定性，作為風險規劃依據","把單一模擬值當成確定事件","只挑符合期待的情境","完全不需觀測資料"],"A","模型是情境與機率工具，需比較假設、範圍與不確定性，並與觀測資料交叉檢驗。","先讀模型假設與區間，再決定能支持何種規劃。"),
("農民因乾旱風險增加而改種耐旱品種並調整灌溉，主要是在降低哪項衝擊？",["水資源不足對農業產量的影響","大氣二氧化碳的全部來源","地球自轉","火山噴發規模"],"A","耐旱品種與精準灌溉可降低缺水對作物的影響，是農業調適措施。","連結措施、暴露系統與預期風險。"),
("若某減碳方案大量使用水資源，評估時最需要注意哪個概念？",["不同措施可能有取捨，須做整體生命週期評估","只要減碳就沒有任何環境成本","水資源與氣候完全無關","不用比較替代方案"],"A","政策可能同時影響能源、土地、水與生態，應比較生命週期與跨部門取捨。","避免只看單一目標，加入副作用與替代方案。"),
("社區建立高溫警報、避暑中心與弱勢名冊，最直接的目的為何？",["降低熱浪造成的健康風險","增加熱浪發生次數","改變地球公轉","使所有城市氣溫相同"],"A","預警與社會支持可讓高風險者提早避暑與就醫，降低熱浪健康衝擊。","確認措施作用在資訊、照護與暴露管理，而非改變氣候成因。"),
("判斷一項氣候政策是否有效，最好的長期設計為何？",["先定義指標與基準，再持續監測排放、風險與公平性並調整","只在政策公布當天調查","只看宣傳口號","不必記錄受影響族群"],"A","有基準、可量測指標與持續監測，才能判斷政策效果及分配影響，並依證據修正。","建立基準線、指標、時間序列與公平性檢核。"),
]
for i,(prompt,opts,ans,ex,strategy) in enumerate(DATA,1):
 p=D/f'question-science-content-nb-{i}.json'; old=json.loads(p.read_text()); text=opts[ord(ans)-65]
 old.update({'prompt':prompt,'options':[{'id':chr(65+j),'text':x} for j,x in enumerate(opts)],'answer':{'value':ans,'explanation':ex+f' 正確答案為選項 {ans}：「{text}」。'},'solutionStrategy':strategy,'solutionSteps':['定位概念：圈出 Nb 氣候變遷的證據、成因、風險、減緩或調適措施。','整理證據：分開危害、暴露、脆弱度、排放來源與政策指標。',f'套用原理：{ex}',f'排除干擾：檢查措施作用層次、資料尺度與不確定性，正確選項是「{text}」。',f'最後回查：答案「{text}」符合題幹，不把情境推估誇大成確定預言。'],'reviewStatus':'draft','updatedAt':'2026-09-08'})
 p.write_text(json.dumps(old,ensure_ascii=False,indent=2)+'\n')
print(f'rewrote {len(DATA)} questions')
